/**
 * `npm run components:generate`: writes the files TypeScript can't derive
 * from the component definitions (03 §2.2).
 *
 * Today that is `@postkit/astro`: one `.astro` wrapper per definition, the
 * React bridge entries and the Astro component map. With `--check` it writes
 * nothing and fails when a generated file is stale, or when a definition has
 * no view in a renderer that claims it (03 §2.1).
 *
 * Inputs are the built packages: `@postkit/core` (definitions),
 * `@postkit/chakra` and `@postkit/react` (views, and the headless renderer's
 * `chakraOnly` exceptions).
 */
import {
  mkdirSync,
  readFileSync,
  readdirSync,
  rmSync,
  writeFileSync,
} from 'node:fs';
import { join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

import { format, resolveConfig } from 'prettier';

const workspaceRoot = fileURLToPath(new URL('../', import.meta.url));
const check = process.argv.includes('--check');
const command = 'npm run components:generate';
const header = `GENERATED by \`${command}\`. Do not edit.`;

async function importBuilt(path) {
  try {
    return await import(new URL(`../${path}`, import.meta.url).href);
  } catch (error) {
    throw new Error(
      `Can't load ${path}. Build it first (${command} builds it for you).`,
      { cause: error },
    );
  }
}

const { postkitBuiltInDefinitions } = await importBuilt(
  'packages/core/dist/components/index.js',
);
const chakra = await importBuilt('packages/chakra/dist/index.js');
const headless = await importBuilt('packages/react/dist/index.js');

const definitions = Object.values(postkitBuiltInDefinitions).sort((a, b) =>
  a.name.localeCompare(b.name),
);
const definitionNames = new Set(definitions.map(({ name }) => name));

/*
 * Renderers and the definitions each one claims. `@postkit/chakra` renders the
 * whole catalog. `@postkit/react` (headless) claims everything except its
 * `chakraOnly` exceptions: interactive components whose behaviour hook hasn't
 * shipped (03 D11 consequence).
 */
const chakraOnly = new Set(headless.chakraOnly ?? []);
const renderers = [
  {
    name: '@postkit/chakra',
    views: chakra,
    claims: () => true,
  },
  {
    name: '@postkit/react',
    views: headless,
    claims: ({ name }) => !chakraOnly.has(name),
  },
];

/*
 * The Astro hydration policy, by definition runtime. `static` and
 * `native-controls` (browser media, `<details>`) components render on the
 * server only. `client` and `resolver` components need React in the browser
 * and hydrate when they approach the viewport. The policy is documented in
 * `packages/astro/README.md` ("Hydration policy"); the check below keeps the
 * two in step.
 */
const hydrationPolicy = Object.freeze({
  static: undefined,
  'native-controls': undefined,
  client: 'client:visible',
  resolver: 'client:visible',
});

function hydrationOf(definition) {
  if (!Object.hasOwn(hydrationPolicy, definition.runtime)) {
    throw new Error(
      `${definition.name}: no Astro hydration policy for runtime "${definition.runtime}".`,
    );
  }
  return hydrationPolicy[definition.runtime];
}

function isComponent(value) {
  return (
    typeof value === 'function' ||
    (typeof value === 'object' && value !== null && '$$typeof' in value)
  );
}

const problems = [];

for (const name of chakraOnly) {
  if (!definitionNames.has(name)) {
    problems.push(
      `@postkit/react lists "${name}" in chakraOnly, but no definition has that name.`,
    );
  }
}
for (const renderer of renderers) {
  for (const definition of definitions) {
    if (!renderer.claims(definition)) continue;
    if (!isComponent(renderer.views[definition.name])) {
      problems.push(
        `${renderer.name} has no view for ${definition.name}. Add one, or (headless only) list it in chakraOnly.`,
      );
    }
  }
}

// --- @postkit/astro --------------------------------------------------------

const astroRoot = join(workspaceRoot, 'packages', 'astro');
const astroComponents = join(astroRoot, 'src', 'components');

function astroWrapper(definition) {
  const { name, runtime } = definition;
  const hydration = hydrationOf(definition);
  const directive = hydration ? ` ${hydration}` : '';
  const policy = hydration
    ? `Hydration: ${hydration} (runtime "${runtime}" needs React in the browser).`
    : `Hydration: none (runtime "${runtime}" renders on the server only).`;
  // Authored MDX children cross the Astro-to-React boundary only when present,
  // so an empty wrapper never hands the view an empty slot.
  const element =
    definition.children === 'mdx'
      ? `{
  Astro.slots.has('default') ? (
    <${name} {...props}${directive}>
      <slot />
    </${name}>
  ) : (
    <${name} {...props}${directive} />
  )
}`
      : `<${name} {...props}${directive} />`;

  return `---
// ${header}
// ${policy}
import type { ${name}Props } from '@postkit/chakra';
import { ${name} } from '../lib/react-bridges';

type Props = ${name}Props;
const props = Astro.props;
---

${element}
`;
}

function reactBridges() {
  const names = definitions.map(({ name }) => name);
  return `// ${header}
import type { SystemContext } from '@chakra-ui/react';
import {
  PostkitProvider,
${names.map((name) => `  ${name} as ${name}View,\n  type ${name}Props,`).join('\n')}
} from '@postkit/chakra';
import system from 'virtual:postkit/chakra-system';
import type { ComponentType } from 'react';

/**
 * Wraps a view in Postkit's provider so each isolated Astro rendering
 * boundary (static render or island) gets the site's Chakra system.
 */
function withPostkitAstroProvider<TProps extends object>(
  Component: ComponentType<TProps>,
) {
  function AstroBridge(props: TProps) {
    return (
      <PostkitProvider system={system as SystemContext}>
        <Component {...props} />
      </PostkitProvider>
    );
  }

  AstroBridge.displayName = Component.displayName ?? Component.name;
  return AstroBridge;
}

${definitions
  .map(
    ({ name, runtime }) =>
      `/** ${name} in Postkit's provider. Its Astro wrapper ${hydrationOf({ name, runtime }) ? `hydrates with ${hydrationOf({ name, runtime })}` : 'renders on the server only'} (runtime "${runtime}"). */
export const ${name} = withPostkitAstroProvider<${name}Props>(${name}View);`,
  )
  .join('\n')}
`;
}

function componentMap() {
  const names = definitions.map(({ name }) => name);
  return `// ${header}
${names.map((name) => `import ${name} from '../components/${name}.astro';`).join('\n')}

export interface PostkitAstroComponents {
${names.map((name) => `  readonly ${name}: typeof ${name};`).join('\n')}
}

export const postkitAstroComponents: PostkitAstroComponents = Object.freeze({
${names.map((name) => `  ${name},`).join('\n')}
});

export function createPostkitAstroComponents<
  TComponents extends object = object,
>(
  components: TComponents = {} as TComponents,
): PostkitAstroComponents & TComponents {
  return {
    ...postkitAstroComponents,
    ...components,
  };
}
`;
}

async function formatTypeScript(path, source) {
  const options = (await resolveConfig(path)) ?? {};
  return format(source, { ...options, filepath: path });
}

const outputs = new Map();
for (const definition of definitions) {
  outputs.set(
    join(astroComponents, `${definition.name}.astro`),
    astroWrapper(definition),
  );
}
for (const [path, source] of [
  [join(astroRoot, 'src', 'lib', 'react-bridges.tsx'), reactBridges()],
  [join(astroRoot, 'src', 'lib', 'components.ts'), componentMap()],
]) {
  outputs.set(path, await formatTypeScript(path, source));
}

// Files in the generated directory that no definition produces.
const orphans = readdirSync(astroComponents, { withFileTypes: true })
  .filter((entry) => entry.isFile() && entry.name.endsWith('.astro'))
  .map((entry) => join(astroComponents, entry.name))
  .filter((path) => !outputs.has(path));

// The README documents every hydrated component (AGENTS.md invariant).
const readme = readFileSync(join(astroRoot, 'README.md'), 'utf8');
const policySection = /^## Hydration policy\n([\s\S]*?)(?=^## )/m.exec(
  readme,
)?.[1];
if (!policySection) {
  problems.push(
    'packages/astro/README.md has no "## Hydration policy" section.',
  );
} else {
  for (const definition of definitions) {
    const hydration = hydrationOf(definition);
    if (
      hydration &&
      !new RegExp(`\\b${definition.name}\\b`).test(policySection)
    ) {
      problems.push(
        `packages/astro/README.md "Hydration policy" doesn't mention ${definition.name} (${hydration}).`,
      );
    }
  }
}

const display = (path) => relative(workspaceRoot, path);

if (check) {
  const stale = [];
  for (const [path, source] of outputs) {
    let existing;
    try {
      existing = readFileSync(path, 'utf8');
    } catch {
      existing = undefined;
    }
    if (existing !== source) stale.push(display(path));
  }
  stale.push(...orphans.map((path) => `${display(path)} (no definition)`));
  if (stale.length > 0) {
    problems.push(
      `Generated component files are stale. Run ${command}.\n  ${stale.join('\n  ')}`,
    );
  }
  if (problems.length > 0) {
    throw new Error(problems.join('\n'));
  }
  process.stdout.write(
    `Generated component files are current (${definitions.length} definitions).\n`,
  );
} else {
  if (problems.length > 0) {
    throw new Error(problems.join('\n'));
  }
  mkdirSync(astroComponents, { recursive: true });
  for (const [path, source] of outputs) writeFileSync(path, source);
  for (const path of orphans) rmSync(path);
  process.stdout.write(
    `Generated ${outputs.size} files for ${definitions.length} definitions` +
      (orphans.length ? `; removed ${orphans.map(display).join(', ')}` : '') +
      '.\n',
  );
}
